#include <jni.h>
#include <dlfcn.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t changed = PTHREAD_COND_INITIALIZER;
static bool done;
static void* worker(void* arg) {
    (void)arg;
    pthread_mutex_lock(&mutex);
    while (!done) { pthread_cond_wait(&changed, &mutex); }
    pthread_mutex_unlock(&mutex);
    return NULL;
}
int main(void) {
    pthread_t thread;
    if (pthread_create(&thread, NULL, worker, NULL)) { return 1; }
    void* handle = dlopen("/usr/lib/jvm/java-25-openjdk/lib/server/libjvm.so", RTLD_NOW | RTLD_GLOBAL);
    if (!handle) { fprintf(stderr, "%s\n", dlerror()); return 2; }
    jint (*create)(JavaVM**, void**, void*) = dlsym(handle, "JNI_CreateJavaVM");
    if (!create) { return 3; }
    JavaVM* vm = NULL;
    JNIEnv* env = NULL;
    JavaVMOption options[] = {
        {.optionString = "-Xint"},
        {.optionString = "-XX:-UseCompressedOops"},
        {.optionString = "-Xshare:off"},
        {.optionString = "-XX:+UseSerialGC"},
        {.optionString = "-Xcheck:jni"},
        {.optionString = "-Djava.class.path=/results:/usr/share/java/postgresql.jar"},
    };
    JavaVMInitArgs args = {.version = JNI_VERSION_1_8, .nOptions = 6, .options = options};
    if (create(&vm, (void**)&env, &args) != JNI_OK) { return 4; }
    jclass cls = (*env)->FindClass(env, "VmControl");
    if ((*env)->ExceptionCheck(env) || !cls) { return 5; }
    jmethodID run = (*env)->GetStaticMethodID(env, cls, "run", "()V");
    if ((*env)->ExceptionCheck(env) || !run) { return 6; }
    (*env)->CallStaticVoidMethod(env, cls, run);
    if ((*env)->ExceptionCheck(env)) { (*env)->ExceptionDescribe(env); return 7; }
    (*env)->DeleteLocalRef(env, cls);
    if ((*vm)->DestroyJavaVM(vm) != JNI_OK) { return 8; }
    pthread_mutex_lock(&mutex);
    done = true;
    pthread_cond_signal(&changed);
    pthread_mutex_unlock(&mutex);
    pthread_join(thread, NULL);
    /* Keep the JVM mapped, matching its lifetime in the bridge host. */
    return 0;
}

