import java.io.File;
import java.net.InetAddress;
import java.net.ServerSocket;
import java.util.HashMap;
public final class VmControl {
    public static void run() throws Exception {
        if (!new File("/usr/share/java/postgresql.jar").exists()) { throw new AssertionError("driver absent"); }
        Class.forName("org.postgresql.Driver");
        try (ServerSocket socket = new ServerSocket(0, 1, InetAddress.getLoopbackAddress())) {
            if (socket.getLocalPort() <= 0) { throw new AssertionError("socket not bound"); }
        }
        Thread thread = new Thread(() -> {
            HashMap<String, Integer> map = new HashMap<>();
            map.put("fixture", 1);
            if (map.get("fixture") != 1) { throw new AssertionError("bad map"); }
        });
        thread.start();
        thread.join();
    }
}

